function chart(id,xmin,xmax,ymin,ymax,xlabel,ylabel,options={}){const canvas=$(id),g=canvas.getContext('2d'),W=canvas.width,H=canvas.height,L=73,R=26,T=35,B=58;g.clearRect(0,0,W,H);const xx=x=>L+(x-xmin)/(xmax-xmin)*(W-L-R),yy=y=>H-B-(y-ymin)/(ymax-ymin)*(H-T-B);g.font='18px -apple-system,sans-serif';g.lineWidth=1;const xticks=options.xticks||Array.from({length:6},(_,k)=>{const value=xmin+(xmax-xmin)*k/5;return{value,label:tick(value)}});g.textAlign='center';for(const {value,label} of xticks){g.strokeStyle=C.grid;g.beginPath();g.moveTo(xx(value),T);g.lineTo(xx(value),H-B);g.stroke();g.fillStyle=C.muted;g.fillText(label,xx(value),H-B+28)}const yticks=options.yticks||Array.from({length:6},(_,k)=>ymin+(ymax-ymin)*k/5);for(const y of yticks){g.strokeStyle=C.grid;g.beginPath();g.moveTo(L,yy(y));g.lineTo(W-R,yy(y));g.stroke();g.fillStyle=C.muted;g.textAlign='right';g.fillText(tick(y),L-13,yy(y)+6)}g.fillStyle=C.muted;g.font='17px -apple-system,sans-serif';g.textAlign='center';g.fillText(xlabel,W/2,H-6);g.textAlign='left';g.fillText(ylabel,L,T-13);function clipped(fn){g.save();g.beginPath();g.rect(L,T,W-L-R,H-T-B);g.clip();fn();g.restore()}const p={g,xx,yy,W,H,L,R,T,B,xmin,xmax,ymin,ymax,clipped,line(points,color=C.teal,width=3,dash=[]){clipped(()=>{g.strokeStyle=color;g.lineWidth=width;g.setLineDash(dash);g.beginPath();let active=false;points.forEach(q=>{if(!Number.isFinite(q.x)||!Number.isFinite(q.y)){active=false;return}if(!active){g.moveTo(xx(q.x),yy(q.y));active=true}else g.lineTo(xx(q.x),yy(q.y))});g.stroke();g.setLineDash([])})},dots(points,color=C.blue,r=5){clipped(()=>{points.forEach(q=>{g.fillStyle=typeof color==='function'?color(q):color;g.beginPath();g.arc(xx(q.x),yy(q.y),r,0,2*Math.PI);g.fill()})})},fn(fn,color=C.teal,width=3,dash=[]){p.line(Array.from({length:301},(_,i)=>{const x=xmin+(xmax-xmin)*i/300;return{x,y:fn(x)}}),color,width,dash)},text(text,x,y,color=C.ink){g.fillStyle=color;g.font='18px -apple-system,sans-serif';g.textAlign='left';g.fillText(text,xx(x),yy(y))}};return p}
function tick(x){const a=Math.abs(x);return a>=1000||(a>0&&a<.001)?x.toExponential(1):Number(x.toFixed(a<.1?4:a<2?2:1)).toString()}

const mainMarkup=$('main').innerHTML;
function update(){if(!current)return;outputs();$('plot2').hidden=true;$('plot3').hidden=true;$('calculation').innerHTML='';$('performance').innerHTML='';lastResult={demo:current.id,parameters:{...state},seed};renderers[current.id]();document.title=current.short+' · Linear Regression Lab'}
function navigate(id){stop();if(id==='references'){references();return}const aliases={'closed-form':'rank-deficient',collinearity:'conditioning',optimization:'gradient-descent'};id=aliases[id]||id;current=DEMOS.find(d=>d.id===id)||DEMOS[0];if(current.id!==id)history.replaceState(null,'','#'+current.id);state={...current.defaults};seed=20260914;$('main').innerHTML=mainMarkup;document.querySelectorAll('.nav-item').forEach(el=>{el.classList.toggle('active',el.dataset.demo===current.id);if(el.dataset.demo===current.id)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});const i=DEMOS.indexOf(current);$('eyebrow').textContent=current.group;$('title').textContent=current.title;$('subtitle').textContent=current.sub;$('motivation').textContent=current.why;$('plotTitle').textContent=current.plot;$('legend').textContent=current.legend;$('formula').innerHTML=current.formula;$('explanation').innerHTML='<p>'+current.explain+'</p>';$('reset').onclick=()=>{stop();state={...current.defaults};seed=20260914;controls();update()};$('next').textContent=i===DEMOS.length-1?'References →':'Next experiment →';$('next').onclick=()=>location.hash=i===DEMOS.length-1?'references':DEMOS[i+1].id;controls();update()}
function action(id){if(id==='radius-small')state.radius=-1.3;if(id==='radius-medium')state.radius=-.5;if(id==='radius-large')state.radius=.2;if(id==='sample')seed+=97;if(id==='fit'){const f=M.scalarFit(lastData.map(q=>q.x),lastData.map(q=>q.y));state.w=f.slope;state.b=f.intercept}if(id==='step'){stop();state.steps=Math.min(250,state.steps+1)}if(id==='stable'){stop();state.eta=Math.log10(1/lastL);state.steps=0}if(id==='run'){if(timer!==null)stop();else{if(state.steps>=250)state.steps=0;timer=setInterval(()=>{state.steps=Math.min(250,state.steps+2);update()},120);const b=document.querySelector('[data-action="run"]');if(b)b.textContent='Pause'}}update()}
function references(){current=null;$('main').innerHTML=`<div class="eyebrow">LINEAR REGRESSION / RESOURCES</div><h1>References and numerical conventions</h1><div class="ref-content"><ul><li><a href="https://cs229.stanford.edu/main_notes.pdf" target="_blank" rel="noopener">Stanford CS229 notes</a>: least squares and optimization.</li><li><a href="https://www.netlib.org/lapack/lug/node27.html" target="_blank" rel="noopener">LAPACK least-squares guide</a>: QR, SVD, and rank-aware solvers.</li><li><a href="https://scikit-learn.org/stable/modules/linear_model.html" target="_blank" rel="noopener">scikit-learn linear models</a>: ridge, lasso, and implementation conventions.</li><li><a href="https://scikit-learn.org/stable/modules/kernel_ridge.html" target="_blank" rel="noopener">Kernel ridge regression</a>: implicit features and nonlinear prediction.</li><li><a href="https://www1.eere.energy.gov/manufacturing/eguide/iso_step_2_4.html" target="_blank" rel="noopener">U.S. Department of Energy</a>: industrial energy prediction.</li></ul><h2>Shared conventions</h2><p>Data loss is SSE/(2n). Ridge adds λ‖w‖₂²/2; lasso adds λ‖w‖₁. Intercepts are unpenalized. The high-dimensional experiments use centered features and responses without an intercept column; θ contains all d slopes. The regularization paths penalize and measure those slopes only. Polynomial features use the monomial basis on training inputs in [−1,1]. Both kernel experiments use an RBF kernel. The radius page uses γ=1/(2ℓ²), and labels its infinite-dimensional implicit feature space separately from the finite n×n Gram matrix. The kernel model centers its Gram matrix and responses and applies the same training centering at prediction time.</p><p>All observations are reproducible simulations. Reset restores the same random sample; Resample changes the seed. Validation data are independent of training data, but repeated tuning on them does not give an unbiased final test score. Repeated model choices based on the displayed test scores also turn that sample into a tuning set. Daily forecasting should respect time order.</p><h2>Test-set performance</h2><p>Every experiment evaluates fitted predictions on 300 reproducible test observations. Test data are generated by a separate random stream and never used to fit models or estimate preprocessing statistics. Models on the same page use the same test sample. Changing coefficients, λ, kernel radius, or a display range keeps that sample fixed. Resample redraws the relevant training, validation, and test samples; Reset restores the original samples.</p><p>For test residuals eᵢ=yᵢ−ŷᵢ: MAE=Σ|eᵢ|/m; MSE=Σeᵢ²/m; RMSE=√MSE; R²=1−Σeᵢ²/Σ(yᵢ−ȳtest)². MAE and RMSE use response units; MSE uses squared response units. R² uses the test target mean, can be negative, and is displayed as undefined for constant test targets. Scores for different underlying datasets should not be compared as if they measured the same task.</p><h2>Solvers and diagnostics</h2><p>OLS uses a direct one-sided Jacobi SVD and returns a minimum-norm solution when needed. Ridge uses a direct-SVD spectral solution for the high-dimensional norm paths and augmented least squares in the other examples. The conditioning experiment uses known singular factors to construct exact OLS solutions and is verified against direct SVD. Its perturbation is deliberately aligned with the weakest direction; resampling preserves the prescribed singular values. Lasso uses coordinate descent with warm starts and displays its KKT residual and convergence status. Path solutions are checked against the original data. The numerical ℓ₀ count uses |θⱼ|>10⁻⁸; no rounding is applied to the actual coefficients. The centered kernel system is solved spectrally. The gradient-descent chart reports its curvature bound and stops at a numerical display limit.</p><button class="primary" onclick="location.hash='fit'">Return to electricity example</button></div>`;document.title='References · Linear Regression Lab'}
createNav();addEventListener('hashchange',()=>navigate(location.hash.slice(1)));navigate(location.hash.slice(1)||'fit');
window.RegressionLab={getState:()=>({demo:current?.id||'references',parameters:{...state},seed,result:JSON.parse(JSON.stringify(lastResult))}),navigate(id){if(!DEMOS.some(d=>d.id===id)&&id!=='references')throw new Error('Unknown experiment');history.replaceState(null,'','#'+id);navigate(id);return this.getState()},configure(parameters){if(!current)throw new Error('Select an experiment first');stop();const next={...state};for(const [key,value] of Object.entries(parameters)){const c=current.controls.find(c=>c[0]===key);if(!c)throw new Error('Unknown parameter '+key);if(Array.isArray(c[2])){if(!c[2].some(([v])=>v===value))throw new Error('Invalid parameter option')}else if(typeof value!=='number'||!Number.isFinite(value)||value<c[2]||value>c[3]||(c[4]>=1&&!Number.isInteger(value)))throw new Error('Parameter out of range');next[key]=value}state=next;update();return this.getState()},action(id){if(!current?.buttons.some(([v])=>v===id))throw new Error('Unknown action');action(id);return this.getState()}};
if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const t of [{name:'read_regression_experiment',description:'Read the current linear regression experiment and numerical metrics',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>window.RegressionLab.getState()},{name:'open_regression_experiment',description:'Open a linear regression experiment',inputSchema:{type:'object',properties:{demo:{type:'string',enum:DEMOS.map(d=>d.id)}},required:['demo'],additionalProperties:false},annotations:{readOnlyHint:false},execute:i=>window.RegressionLab.navigate(i.demo)},{name:'configure_regression_experiment',description:'Update parameters within the visible control ranges',inputSchema:{type:'object',properties:{parameters:{type:'object'}},required:['parameters'],additionalProperties:false},annotations:{readOnlyHint:false},execute:i=>window.RegressionLab.configure(i.parameters)}]){try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{})}catch{}}addEventListener('pagehide',()=>{stop();lifecycle.abort()},{once:true})}
